import React from 'react'
import { useNavigate } from 'react-router-dom';
import { useState } from 'react';
import axios from 'axios';

function Register() {
    const navigate = useNavigate();
    const [user, setUser] = useState({
        fullname: '',
        email: '',
        password: '',
        phone: ''
    });
    const { fullname, email, password, phone } = user;

    const onInputChange = async(e) => {
        setUser({ ...user, [e.target.name]: e.target.value });
    }

    const onSubmit = async(e) => {
        e.preventDefault();
        await axios.post("http://localhost:8080/user", user);
        alert("User registered successfully");
        window.location.href = "/login";
    }

  return (
    <div>
      <h1>Register</h1>
      <form onSubmit={(e) => onSubmit(e)}>

        <label htmlFor="fullname">fullname</label><br />
        <input type="text" id="fullname" name="fullname" 
        onChange={(e) => {
            const re = /^[a-zA-Z\s]*$/;
            if (e.test(e.target.value))
                onInputChange(e);
            }}
            value={fullname} required />
        <br />  

        <label htmlFor="email">email</label><br />
        <input type="email" id="email" name="email" value={email} onChange={(e) => onInputChange(e)} required /><br />

        <label htmlFor="password">password</label><br />
        <input type="password" id="password" name="password" value={password} onChange={(e) => onInputChange(e)} required /><br />

        <label htmlFor="phone">phone</label><br />
        <input 
        type="text" 
        id="phone" 
        value={phone} 
        onChange={(e) => {
            const re = /^[0-9\b]{0,10}$/;
            if (e.test(e.target.value)) {
                onInputChange(e);
            }
        }}
        maxLength="10"
        pattern="[0-9]{10}"
        title='please enter exactly 10 didgits . '
        name="phone"/>
        <br />
        
        <button type="submit" className="fom_btn">register</button>
      </form>
    </div>
  )
}

export default Register
